import re

class ASTNode:
    def __init__(self, type_name, **kwargs):
        self.type = type_name
        self.line = kwargs.get('line', 1)
        self.col = kwargs.get('col', 1)
        for k, v in kwargs.items():
            setattr(self, k, v)

    def __repr__(self):
        attrs = [f"{k}={repr(v)}" for k, v in self.__dict__.items() if k not in ('type', 'line', 'col')]
        return f"{self.type}({', '.join(attrs)})"

def tokenize(code):
    tokens = []
    i = 0
    n = len(code)
    line = 1
    col = 1

    ops = [
        '>>>=', '===', '!==', '>>>', '...', '**=', '<<=', '>>=',
        '==', '!=', '<=', '>=', '&&', '||', '??', '?.', '**',
        '++', '--', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=',
        '=>', '<<', '>>',
        '+', '-', '*', '/', '%', '<', '>', '=', '!', '&', '|', '^', '~',
        '?', ':', '.', ',', ';', '(', ')', '{', '}', '[', ']'
    ]

    keywords = {
        'var', 'let', 'const', 'function', 'if', 'else', 'while', 'do', 'for',
        'in', 'of', 'return', 'break', 'continue', 'switch', 'case', 'default',
        'try', 'catch', 'finally', 'throw', 'new', 'typeof', 'instanceof',
        'delete', 'import', 'export', 'from', 'as', 'true', 'false', 'null',
        'undefined', 'async', 'await', 'class', 'extends', 'super', 'this', 'void'
    }

    last_token_type = None

    while i < n:
        c = code[i]

        # Whitespace
        if c in ' \t\r\n':
            if c == '\n':
                line += 1
                col = 1
            else:
                col += 1
            i += 1
            continue

        # Single-line comment
        if code.startswith('//', i):
            i += 2
            while i < n and code[i] != '\n':
                i += 1
            continue

        # Multi-line comment
        if code.startswith('/*', i):
            i += 2
            while i < n - 1 and not code.startswith('*/', i):
                if code[i] == '\n':
                    line += 1
                    col = 1
                else:
                    col += 1
                i += 1
            i += 2
            continue

        # Regex literal check (if '/' follows an expression operator or start)
        if c == '/' and last_token_type in (None, 'PUNCT_OP', 'KEYWORD_EXPR', 'PUNCT_OPEN'):
            # Parse regex
            start = i
            i += 1
            in_class = False
            escaped = False
            pattern = []
            while i < n:
                ch = code[i]
                if escaped:
                    pattern.append('\\' + ch)
                    escaped = False
                elif ch == '\\':
                    escaped = True
                elif ch == '[':
                    in_class = True
                    pattern.append(ch)
                elif ch == ']':
                    in_class = False
                    pattern.append(ch)
                elif ch == '/' and not in_class:
                    i += 1
                    break
                else:
                    pattern.append(ch)
                i += 1
            # flags
            flags = []
            while i < n and code[i].isalpha():
                flags.append(code[i])
                i += 1
            tokens.append(('REGEX', (''.join(pattern), ''.join(flags)), line, col))
            last_token_type = 'VAL'
            col += (i - start)
            continue

        # Number literal
