class ASTNode:
    def __init__(self, type_name, **kwargs):
        self.type = type_name
        self.line = kwargs.get('line', 1)
        self.col = kwargs.get('col', 1)
        for k, v in kwargs.items():
            setattr(self, k, v)

    def __repr__(self):
        attrs = [f"{k}={repr(v)}" for k, v in self.__dict__.items() if k not in ('type', 'line', 'col')]
