#!/usr/bin/env python3
import sys, os, math, time, json, re, subprocess

# --- AST Nodes ---
class ASTNode:
    def __init__(self, type_name, **kwargs):
        self.type = type_name
        self.line = kwargs.get('line', 1)
        self.col = kwargs.get('col', 1)
