            setattr(self, k, v)

# --- Tokenizer ---
def tokenize(code):
    tokens = []
    i = 0
    n = len(code)
    line = 1
    col = 1

    ops = [
        '>>>=', '===', '!==', '>>>', '...', '**=', '<<=', '>>=',
        '==', '!=', '<=', '>=', '&&', '||', '??', '?.', '**',
        '++', '--', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=',
        '=>', '<<', '>>',
        '+', '-', '*', '/', '%', '<', '>', '=', '!', '&', '|', '^', '~',
        '?', ':', '.', ',', ';', '(', ')', '{', '}', '[', ']'
