    math_obj.set('round', make_native_fn('round', lambda t, *a: round(a[0]) if a else 0))
    math_obj.set('min', make_native_fn('min', lambda t, *a: min(a) if a else float('inf')))
    math_obj.set('max', make_native_fn('max', lambda t, *a: max(a) if a else float('-inf')))
    math_obj.set('sqrt', make_native_fn('sqrt', lambda t, *a: math.sqrt(a[0]) if a else 0))
    math_obj.set('pow', make_native_fn('pow', lambda t, *a: math.pow(a[0], a[1]) if len(a) > 1 else 0))

    GLOBAL_OBJECT.set('Math', math_obj)
    GLOBAL_ENV.declare('Math', math_obj)

    # JSON
    json_obj = JSObject(OBJECT_PROTOTYPE)
    json_obj.set('stringify', make_native_fn('stringify', lambda t, *a: json.dumps(a[0]) if a else "undefined"))
    json_obj.set('parse', make_native_fn('parse', lambda t, *a: json.loads(a[0]) if a else None))

    GLOBAL_OBJECT.set('JSON', json_obj)
    GLOBAL_ENV.declare('JSON', json_obj)

    # std Module
    def create_std_module():
        std_obj = JSObject(OBJECT_PROTOTYPE)

        def std_printf(t, *args):
            if not args: return 0
            fmt = js_to_string(args[0])
            vals = args[1:]
            try:
                out_str = fmt % tuple(vals)
                sys.stdout.write(out_str)
                sys.stdout.flush()
                return len(out_str)
            except Exception:
                sys.stdout.write(fmt)
                sys.stdout.flush()
                return len(fmt)

        def std_sprintf(t, *args):
            if not args: return ""
            fmt = js_to_string(args[0])
            vals = args[1:]
            try:
                return fmt % tuple(vals)
            except Exception:
                return fmt

        def std_load_file(t, *args):
            if not args: return JS_NULL
            path = js_to_string(args[0])
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    return f.read()
            except Exception:
                return JS_NULL

        def std_getenv(t, *args):
            if not args: return JS_UNDEFINED
            name = js_to_string(args[0])
            val = os.getenv(name)
            return val if val is not None else JS_UNDEFINED

        def std_setenv(t, *args):
            if len(args) < 2: return
            os.environ[js_to_string(args[0])] = js_to_string(args[1])

        def std_unsetenv(t, *args):
            if args:
                os.environ.pop(js_to_string(args[0]), None)

        def std_exit(t, *args):
            code = int(args[0]) if args else 0
            sys.exit(code)

        file_proto = JSObject(OBJECT_PROTOTYPE)

        def make_file_obj(py_file):
            f_obj = JSObject(file_proto)
            f_obj.set('puts', make_native_fn('puts', lambda t, *a: py_file.write(js_to_string(a[0])) if a else 0))
            f_obj.set('printf', make_native_fn('printf', lambda t, *a: std_printf(t, *a)))
            f_obj.set('flush', make_native_fn('flush', lambda t, *a: py_file.flush()))
            f_obj.set('close', make_native_fn('close', lambda t, *a: py_file.close()))
            f_obj.set('getline', make_native_fn('getline', lambda t, *a: py_file.readline().rstrip('\r\n')))
            f_obj.set('readAsString', make_native_fn('readAsString', lambda t, *a: py_file.read()))
            return f_obj

        def std_open(t, *args):
            if len(args) < 2: return JS_NULL
            filename = js_to_string(args[0])
            mode = js_to_string(args[1])
            try:
                f = open(filename, mode)
                return make_file_obj(f)
            except Exception:
                return JS_NULL

        std_obj.set('out', make_file_obj(sys.stdout))
        std_obj.set('err', make_file_obj(sys.stderr))
        std_obj.set('in', make_file_obj(sys.stdin))
        std_obj.set('printf', make_native_fn('printf', std_printf))
        std_obj.set('sprintf', make_native_fn('sprintf', std_sprintf))
        std_obj.set('loadFile', make_native_fn('loadFile', std_load_file))
        std_obj.set('open', make_native_fn('open', std_open))
        std_obj.set('getenv', make_native_fn('getenv', std_getenv))
        std_obj.set('setenv', make_native_fn('setenv', std_setenv))
        std_obj.set('unsetenv', make_native_fn('unsetenv', std_unsetenv))
        std_obj.set('exit', make_native_fn('exit', std_exit))
        std_obj.set('SEEK_SET', 0)
        std_obj.set('SEEK_CUR', 1)
        std_obj.set('SEEK_END', 2)

        return std_obj

    # os Module
    def create_os_module():
        os_obj = JSObject(OBJECT_PROTOTYPE)
        os_obj.set('platform', 'linux')
        os_obj.set('getcwd', make_native_fn('getcwd', lambda t, *a: os.getcwd()))
        os_obj.set('chdir', make_native_fn('chdir', lambda t, *a: os.chdir(js_to_string(a[0])) if a else None))
        os_obj.set('mkdir', make_native_fn('mkdir', lambda t, *a: os.mkdir(js_to_string(a[0])) if a else None))
        os_obj.set('remove', make_native_fn('remove', lambda t, *a: os.remove(js_to_string(a[0])) if a else None))
        os_obj.set('rename', make_native_fn('rename', lambda t, *a: os.rename(js_to_string(a[0]), js_to_string(a[1])) if len(a) >= 2 else None))
        os_obj.set('realpath', make_native_fn('realpath', lambda t, *a: os.path.realpath(js_to_string(a[0])) if a else ""))
        os_obj.set('isatty', make_native_fn('isatty', lambda t, *a: os.isatty(a[0]) if a else False))
        os_obj.set('sleep', make_native_fn('sleep', lambda t, *a: time.sleep(a[0] / 1000.0) if a else None))

        os_obj.set('O_RDONLY', os.O_RDONLY)
        os_obj.set('O_WRONLY', os.O_WRONLY)
        os_obj.set('O_RDWR', os.O_RDWR)
        os_obj.set('O_CREAT', os.O_CREAT)
        os_obj.set('O_TRUNC', os.O_TRUNC)
        os_obj.set('O_APPEND', os.O_APPEND)

        return os_obj

    return create_std_module(), create_os_module()

# --- AST Nodes ---
class ASTNode:
    def __init__(self, type_name, **kwargs):
        self.type = type_name
        self.line = kwargs.get('line', 1)
        self.col = kwargs.get('col', 1)
        for k, v in kwargs.items():
            setattr(self, k, v)

# --- Tokenizer ---
def tokenize(code):
    tokens = []
    i = 0
    n = len(code)
    line = 1
    col = 1

    ops = [
        '>>>=', '===', '!==', '>>>', '...', '**=', '<<=', '>>=',
        '==', '!=', '<=', '>=', '&&', '||', '??', '?.', '**',
        '++', '--', '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=',
        '=>', '<<', '>>',
        '+', '-', '*', '/', '%', '<', '>', '=', '!', '&', '|', '^', '~',
        '?', ':', '.', ',', ';', '(', ')', '{', '}', '[', ']'
    ]

    keywords = {
        'var', 'let', 'const', 'function', 'if', 'else', 'while', 'do', 'for',
        'in', 'of', 'return', 'break', 'continue', 'switch', 'case', 'default',
        'try', 'catch', 'finally', 'throw', 'new', 'typeof', 'instanceof',
        'delete', 'import', 'export', 'from', 'as', 'true', 'false', 'null',
        'undefined', 'async', 'await', 'class', 'extends', 'super', 'this', 'void'
    }

    last_token_type = None

    while i < n:
        c = code[i]

        if c in ' \t\r\n':
            if c == '\n':
                line += 1
                col = 1
            else:
                col += 1
            i += 1
            continue

        if code.startswith('//', i):
            i += 2
            while i < n and code[i] != '\n':
                i += 1
            continue

        if code.startswith('/*', i):
            i += 2
            while i < n - 1 and not code.startswith('*/', i):
                if code[i] == '\n':
                    line += 1
                    col = 1
                else:
                    col += 1
                i += 1
            i += 2
            continue

        if c == '/' and last_token_type in (None, 'PUNCT_OP', 'KEYWORD_EXPR', 'PUNCT_OPEN'):
            start = i
            i += 1
            in_class = False
            escaped = False
            pattern = []
            while i < n:
                ch = code[i]
                if escaped:
                    pattern.append('\\' + ch)
                    escaped = False
                elif ch == '\\':
                    escaped = True
                elif ch == '[':
                    in_class = True
                    pattern.append(ch)
                elif ch == ']':
                    in_class = False
                    pattern.append(ch)
                elif ch == '/' and not in_class:
                    i += 1
                    break
                else:
                    pattern.append(ch)
                i += 1
            flags = []
            while i < n and code[i].isalpha():
                flags.append(code[i])
                i += 1
            tokens.append(('REGEX', (''.join(pattern), ''.join(flags)), line, col))
            last_token_type = 'VAL'
            col += (i - start)
            continue

        if c.isdigit() or (c == '.' and i + 1 < n and code[i+1].isdigit()):
            start = i
            if c == '0' and i + 1 < n and code[i+1] in 'xXoObB':
                i += 2
                while i < n and code[i].isalnum():
                    i += 1
            else:
                while i < n and (code[i].isdigit() or code[i] in '.eE'):
                    if code[i] in 'eE' and i + 1 < n and code[i+1] in '+-':
                        i += 1
                    i += 1
            num_str = code[start:i]
            tokens.append(('NUMBER', num_str, line, col))
            last_token_type = 'VAL'
            col += (i - start)
            continue

        if c in '"\'':
            quote = c
            start = i
            i += 1
            s = []
            while i < n and code[i] != quote:
                if code[i] == '\\' and i + 1 < n:
                    i += 1
                    esc = code[i]
                    if esc == 'n': s.append('\n')
                    elif esc == 'r': s.append('\r')
                    elif esc == 't': s.append('\t')
                    elif esc == '0': s.append('\0')
                    elif esc == '\\': s.append('\\')
                    elif esc == quote: s.append(quote)
                    else: s.append(esc)
                else:
                    s.append(code[i])
                i += 1
            i += 1
            tokens.append(('STRING', ''.join(s), line, col))
            last_token_type = 'VAL'
            col += (i - start)
            continue

        if c == '`':
            start = i
            i += 1
            s = []
            while i < n and code[i] != '`':
                if code[i] == '\\' and i + 1 < n:
                    i += 1
                    s.append(code[i])
                else:
                    s.append(code[i])
                i += 1
            i += 1
            tokens.append(('TEMPLATE', ''.join(s), line, col))
            last_token_type = 'VAL'
            col += (i - start)
            continue

        if c.isalpha() or c in '_$':
            start = i
            while i < n and (code[i].isalnum() or code[i] in '_$'):
                i += 1
            word = code[start:i]
            if word in keywords:
                tokens.append(('KEYWORD', word, line, col))
                if word in ('return', 'case', 'throw', 'typeof', 'delete', 'void', 'instanceof', 'in', 'new', 'yield', 'await'):
                    last_token_type = 'KEYWORD_EXPR'
                else:
                    last_token_type = 'KEYWORD'
            else:
                tokens.append(('IDENT', word, line, col))
                last_token_type = 'VAL'
            col += (i - start)
            continue

        matched_op = None
        for op in ops:
            if code.startswith(op, i):
                matched_op = op
                break
        if matched_op:
            tokens.append(('PUNCT', matched_op, line, col))
            if matched_op in ('(', '[', '{'):
                last_token_type = 'PUNCT_OPEN'
            elif matched_op in (')', ']', '}'):
                last_token_type = 'VAL'
            else:
                last_token_type = 'PUNCT_OP'
            i += len(matched_op)
            col += len(matched_op)
            continue

        tokens.append(('PUNCT', c, line, col))
        last_token_type = 'PUNCT_OP'
        i += 1
        col += 1

    tokens.append(('EOF', '', line, col))
    return tokens

# --- Parser ---
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self, offset=0):
        if self.pos + offset < len(self.tokens):
            return self.tokens[self.pos + offset]
        return self.tokens[-1]

    def curr(self): return self.peek(0)

    def match(self, ttype, val=None):
        t = self.curr()
        if t[0] == ttype and (val is None or t[1] == val):
            self.pos += 1
            return t
        return None

    def expect(self, ttype, val=None):
        m = self.match(ttype, val)
        if not m:
            c = self.curr()
            raise SyntaxError(f"Unexpected token '{c[1]}' at line {c[2]}, column {c[3]}")
        return m

    def parse_program(self):
        body = []
        while self.curr()[0] != 'EOF':
            stmt = self.parse_statement()
            if stmt: body.append(stmt)
        return ASTNode('Program', body=body)

    def parse_statement(self):
        t = self.curr()
        if t[0] == 'PUNCT' and t[1] == ';':
            self.pos += 1
            return ASTNode('EmptyStatement', line=t[2], col=t[3])

        if t[0] == 'PUNCT' and t[1] == '{':
            return self.parse_block()

        if t[0] == 'KEYWORD':
            kw = t[1]
            if kw in ('var', 'let', 'const'): return self.parse_variable_declaration()
            elif kw == 'function': return self.parse_function_declaration()
            elif kw == 'if': return self.parse_if_statement()
            elif kw == 'while': return self.parse_while_statement()
            elif kw == 'do': return self.parse_do_while_statement()
            elif kw == 'for': return self.parse_for_statement()
            elif kw == 'return': return self.parse_return_statement()
            elif kw == 'break': return self.parse_break_statement()
            elif kw == 'continue': return self.parse_continue_statement()
            elif kw == 'throw': return self.parse_throw_statement()
            elif kw == 'try': return self.parse_try_statement()
            elif kw == 'switch': return self.parse_switch_statement()
            elif kw == 'import': return self.parse_import_statement()
            elif kw == 'export': return self.parse_export_statement()

        expr = self.parse_expression()
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('ExpressionStatement', expression=expr, line=t[2], col=t[3])

    def parse_block(self):
        t = self.expect('PUNCT', '{')
        body = []
        while self.curr()[0] != 'EOF' and not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
            stmt = self.parse_statement()
            if stmt: body.append(stmt)
        self.expect('PUNCT', '}')
        return ASTNode('BlockStatement', body=body, line=t[2], col=t[3])

    def parse_variable_declaration(self):
        t = self.curr()
        kind = self.expect('KEYWORD')[1]
        decls = []
        while True:
            id_tok = self.expect('IDENT')
            init = None
            if self.match('PUNCT', '='):
                init = self.parse_expression(prec=1)
            decls.append(ASTNode('VariableDeclarator', id=id_tok[1], init=init, line=id_tok[2], col=id_tok[3]))
            if not self.match('PUNCT', ','): break
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('VariableDeclaration', kind=kind, declarations=decls, line=t[2], col=t[3])

    def parse_function_declaration(self):
        t = self.expect('KEYWORD', 'function')
        id_tok = self.expect('IDENT')
        self.expect('PUNCT', '(')
        params = []
        if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
            while True:
                params.append(self.expect('IDENT')[1])
                if not self.match('PUNCT', ','): break
        self.expect('PUNCT', ')')
        body = self.parse_block()
        return ASTNode('FunctionDeclaration', id=id_tok[1], params=params, body=body, line=t[2], col=t[3])

    def parse_if_statement(self):
        t = self.expect('KEYWORD', 'if')
        self.expect('PUNCT', '(')
        test = self.parse_expression()
        self.expect('PUNCT', ')')
        consequent = self.parse_statement()
        alternate = None
        if self.match('KEYWORD', 'else'):
            alternate = self.parse_statement()
        return ASTNode('IfStatement', test=test, consequent=consequent, alternate=alternate, line=t[2], col=t[3])

    def parse_while_statement(self):
        t = self.expect('KEYWORD', 'while')
        self.expect('PUNCT', '(')
        test = self.parse_expression()
        self.expect('PUNCT', ')')
        body = self.parse_statement()
        return ASTNode('WhileStatement', test=test, body=body, line=t[2], col=t[3])

    def parse_do_while_statement(self):
        t = self.expect('KEYWORD', 'do')
        body = self.parse_statement()
        self.expect('KEYWORD', 'while')
        self.expect('PUNCT', '(')
        test = self.parse_expression()
        self.expect('PUNCT', ')')
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('DoWhileStatement', body=body, test=test, line=t[2], col=t[3])

    def parse_for_statement(self):
        t = self.expect('KEYWORD', 'for')
        self.expect('PUNCT', '(')

        kind = None
        if self.curr()[0] == 'KEYWORD' and self.curr()[1] in ('var', 'let', 'const'):
            kind = self.curr()[1]
            if self.peek(1)[0] == 'IDENT' and self.peek(2)[0] == 'KEYWORD' and self.peek(2)[1] in ('in', 'of'):
                self.pos += 1
                id_tok = self.expect('IDENT')
                for_type = self.expect('KEYWORD')[1]
                right = self.parse_expression()
                self.expect('PUNCT', ')')
                body = self.parse_statement()
                decl = ASTNode('VariableDeclaration', kind=kind, declarations=[ASTNode('VariableDeclarator', id=id_tok[1], init=None)])
                if for_type == 'in':
                    return ASTNode('ForInStatement', left=decl, right=right, body=body, line=t[2], col=t[3])
                else:
                    return ASTNode('ForOfStatement', left=decl, right=right, body=body, line=t[2], col=t[3])

        init = None
        if self.curr()[0] == 'KEYWORD' and self.curr()[1] in ('var', 'let', 'const'):
            init = self.parse_variable_declaration()
        elif not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ';'):
            init = self.parse_expression()
            if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
                self.pos += 1
        else:
            self.expect('PUNCT', ';')

        test = None
        if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ';'):
            test = self.parse_expression()
        self.expect('PUNCT', ';')

        update = None
        if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
            update = self.parse_expression()
        self.expect('PUNCT', ')')

        body = self.parse_statement()
        return ASTNode('ForStatement', init=init, test=test, update=update, body=body, line=t[2], col=t[3])

    def parse_return_statement(self):
        t = self.expect('KEYWORD', 'return')
        arg = None
        if self.curr()[0] != 'PUNCT' or self.curr()[1] not in (';', '}'):
            arg = self.parse_expression()
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('ReturnStatement', argument=arg, line=t[2], col=t[3])

    def parse_break_statement(self):
        t = self.expect('KEYWORD', 'break')
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('BreakStatement', line=t[2], col=t[3])

    def parse_continue_statement(self):
        t = self.expect('KEYWORD', 'continue')
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('ContinueStatement', line=t[2], col=t[3])

    def parse_throw_statement(self):
        t = self.expect('KEYWORD', 'throw')
        arg = self.parse_expression()
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('ThrowStatement', argument=arg, line=t[2], col=t[3])

    def parse_try_statement(self):
        t = self.expect('KEYWORD', 'try')
        block = self.parse_block()
        handler = None
        if self.match('KEYWORD', 'catch'):
            param = None
            if self.match('PUNCT', '('):
                param = self.expect('IDENT')[1]
                self.expect('PUNCT', ')')
            catch_block = self.parse_block()
            handler = ASTNode('CatchClause', param=param, body=catch_block)
        finalizer = None
        if self.match('KEYWORD', 'finally'):
            finalizer = self.parse_block()
        return ASTNode('TryStatement', block=block, handler=handler, finalizer=finalizer, line=t[2], col=t[3])

    def parse_switch_statement(self):
        t = self.expect('KEYWORD', 'switch')
        self.expect('PUNCT', '(')
        disc = self.parse_expression()
        self.expect('PUNCT', ')')
        self.expect('PUNCT', '{')
        cases = []
        while self.curr()[0] != 'EOF' and not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
            if self.match('KEYWORD', 'case'):
                test = self.parse_expression()
                self.expect('PUNCT', ':')
                cons = []
                while self.curr()[0] != 'EOF' and not (self.curr()[0] == 'KEYWORD' and self.curr()[1] in ('case', 'default')) and not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
                    stmt = self.parse_statement()
                    if stmt: cons.append(stmt)
                cases.append(ASTNode('SwitchCase', test=test, consequent=cons))
            elif self.match('KEYWORD', 'default'):
                self.expect('PUNCT', ':')
                cons = []
                while self.curr()[0] != 'EOF' and not (self.curr()[0] == 'KEYWORD' and self.curr()[1] in ('case', 'default')) and not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
                    stmt = self.parse_statement()
                    if stmt: cons.append(stmt)
                cases.append(ASTNode('SwitchCase', test=None, consequent=cons))
        self.expect('PUNCT', '}')
        return ASTNode('SwitchStatement', discriminant=disc, cases=cases, line=t[2], col=t[3])

    def parse_import_statement(self):
        t = self.expect('KEYWORD', 'import')
        specifiers = []
        if self.match('PUNCT', '*'):
            self.expect('KEYWORD', 'as')
            alias = self.expect('IDENT')[1]
            specifiers.append(('namespace', alias))
        elif self.match('PUNCT', '{'):
            while not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
                name = self.expect('IDENT')[1]
                alias = name
                if self.match('KEYWORD', 'as'):
                    alias = self.expect('IDENT')[1]
                specifiers.append(('named', name, alias))
                if not self.match('PUNCT', ','): break
            self.expect('PUNCT', '}')
        self.expect('KEYWORD', 'from')
        source = self.expect('STRING')[1]
        if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';':
            self.pos += 1
        return ASTNode('ImportDeclaration', specifiers=specifiers, source=source, line=t[2], col=t[3])

    def parse_export_statement(self):
        t = self.expect('KEYWORD', 'export')
        if self.curr()[0] == 'KEYWORD' and self.curr()[1] in ('var', 'let', 'const', 'function'):
            decl = self.parse_statement()
            return ASTNode('ExportDeclaration', declaration=decl, line=t[2], col=t[3])
        if self.match('KEYWORD', 'default'):
            expr = self.parse_expression()
            if self.curr()[0] == 'PUNCT' and self.curr()[1] == ';': self.pos += 1
            return ASTNode('ExportDefaultDeclaration', declaration=expr, line=t[2], col=t[3])
        return ASTNode('ExportDeclaration', declaration=None, line=t[2], col=t[3])

    PRECEDENCE = {
        '=': 1, '+=': 1, '-=': 1, '*=': 1, '/=': 1, '%=': 1, '**=': 1,
        '?:': 2,
        '||': 3, '??': 3,
        '&&': 4,
        '|': 5, '^': 6, '&': 7,
        '==': 8, '!=': 8, '===': 8, '!==': 8,
        '<': 9, '<=': 9, '>': 9, '>=': 9, 'in': 9, 'instanceof': 9,
        '<<': 10, '>>': 10, '>>>': 10,
        '+': 11, '-': 11,
        '*': 12, '/': 12, '%': 12,
        '**': 13,
    }

    def parse_expression(self, prec=0):
        left = self.parse_primary()

        if isinstance(left, ASTNode) and left.type == 'Identifier' and self.match('PUNCT', '=>'):
            body = self.parse_block() if (self.curr()[0] == 'PUNCT' and self.curr()[1] == '{') else self.parse_expression(prec=1)
            return ASTNode('ArrowFunctionExpression', params=[left.name], body=body, line=left.line, col=left.col)

        while True:
            t = self.curr()
            if t[0] == 'PUNCT' and t[1] == '.':
                self.pos += 1
                prop = self.expect('IDENT')[1]
                left = ASTNode('MemberExpression', object=left, property=prop, computed=False, line=t[2], col=t[3])
                continue
            elif t[0] == 'PUNCT' and t[1] == '[':
                self.pos += 1
                prop = self.parse_expression()
                self.expect('PUNCT', ']')
                left = ASTNode('MemberExpression', object=left, property=prop, computed=True, line=t[2], col=t[3])
                continue
            elif t[0] == 'PUNCT' and t[1] == '(':
                self.pos += 1
                args = []
                if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
                    while True:
                        args.append(self.parse_expression(prec=1))
                        if not self.match('PUNCT', ','): break
                self.expect('PUNCT', ')')
                left = ASTNode('CallExpression', callee=left, arguments=args, line=t[2], col=t[3])
                continue
            elif t[0] == 'PUNCT' and t[1] in ('++', '--'):
                op = t[1]
                self.pos += 1
                left = ASTNode('UpdateExpression', operator=op, argument=left, prefix=False, line=t[2], col=t[3])
                continue

            op = t[1]
            op_prec = self.PRECEDENCE.get(op, 0)
            if op_prec <= prec: break

            self.pos += 1

            if op == '?':
                consequent = self.parse_expression()
                self.expect('PUNCT', ':')
                alternate = self.parse_expression(prec=op_prec - 1)
                left = ASTNode('ConditionalExpression', test=left, consequent=consequent, alternate=alternate, line=t[2], col=t[3])
            elif op in ('=', '+=', '-=', '*=', '/=', '%=', '**=', '&=', '|=', '^='):
                right = self.parse_expression(prec=op_prec - 1)
                left = ASTNode('AssignmentExpression', operator=op, left=left, right=right, line=t[2], col=t[3])
            else:
                right = self.parse_expression(prec=op_prec)
                left = ASTNode('BinaryExpression', operator=op, left=left, right=right, line=t[2], col=t[3])

        return left

    def parse_primary(self):
        t = self.curr()

        if t[0] == 'PUNCT' and t[1] in ('+', '-', '!', '~', '++', '--'):
            op = t[1]
            self.pos += 1
            arg = self.parse_primary()
            if op in ('++', '--'):
                return ASTNode('UpdateExpression', operator=op, argument=arg, prefix=True, line=t[2], col=t[3])
            return ASTNode('UnaryExpression', operator=op, argument=arg, prefix=True, line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] in ('typeof', 'delete', 'void'):
            op = t[1]
            self.pos += 1
            arg = self.parse_primary()
            return ASTNode('UnaryExpression', operator=op, argument=arg, prefix=True, line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'new':
            self.pos += 1
            callee = self.parse_primary()
            args = []
            if self.match('PUNCT', '('):
                if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
                    while True:
                        args.append(self.parse_expression(prec=1))
                        if not self.match('PUNCT', ','): break
                self.expect('PUNCT', ')')
            return ASTNode('NewExpression', callee=callee, arguments=args, line=t[2], col=t[3])

        if t[0] == 'NUMBER':
            self.pos += 1
            val = float(t[1]) if '.' in t[1] or 'e' in t[1] or 'E' in t[1] else int(t[1], 0)
            return ASTNode('Literal', value=val, raw=t[1], line=t[2], col=t[3])

        if t[0] == 'STRING':
            self.pos += 1
            return ASTNode('Literal', value=t[1], raw=t[1], line=t[2], col=t[3])

        if t[0] == 'TEMPLATE':
            self.pos += 1
            return ASTNode('Literal', value=t[1], raw=t[1], line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'true':
            self.pos += 1
            return ASTNode('Literal', value=True, raw='true', line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'false':
            self.pos += 1
            return ASTNode('Literal', value=False, raw='false', line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'null':
            self.pos += 1
            return ASTNode('Literal', value=None, raw='null', line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'undefined':
            self.pos += 1
            return ASTNode('Identifier', name='undefined', line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'this':
            self.pos += 1
            return ASTNode('Identifier', name='this', line=t[2], col=t[3])

        if t[0] == 'IDENT':
            self.pos += 1
            return ASTNode('Identifier', name=t[1], line=t[2], col=t[3])

        if t[0] == 'KEYWORD' and t[1] == 'function':
            self.pos += 1
            name = None
            if self.curr()[0] == 'IDENT':
                name = self.expect('IDENT')[1]
            self.expect('PUNCT', '(')
            params = []
            if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
                while True:
                    params.append(self.expect('IDENT')[1])
                    if not self.match('PUNCT', ','): break
            self.expect('PUNCT', ')')
            body = self.parse_block()
            return ASTNode('FunctionExpression', id=name, params=params, body=body, line=t[2], col=t[3])

        if t[0] == 'PUNCT' and t[1] == '(':
            self.pos += 1
            args = []
            if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
                while True:
                    args.append(self.parse_expression())
                    if not self.match('PUNCT', ','): break
            self.expect('PUNCT', ')')
            if self.match('PUNCT', '=>'):
                params = [a.name for a in args if hasattr(a, 'name')]
                body = self.parse_block() if (self.curr()[0] == 'PUNCT' and self.curr()[1] == '{') else self.parse_expression(prec=1)
                return ASTNode('ArrowFunctionExpression', params=params, body=body, line=t[2], col=t[3])
            return args[0] if len(args) == 1 else ASTNode('SequenceExpression', expressions=args, line=t[2], col=t[3])

        if t[0] == 'PUNCT' and t[1] == '[':
            self.pos += 1
            elements = []
            if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ']'):
                while True:
                    elements.append(self.parse_expression(prec=1))
                    if not self.match('PUNCT', ','): break
            self.expect('PUNCT', ']')
            return ASTNode('ArrayExpression', elements=elements, line=t[2], col=t[3])

        if t[0] == 'PUNCT' and t[1] == '{':
            self.pos += 1
            props = []
            if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == '}'):
                while True:
                    k = self.curr()
                    if k[0] in ('IDENT', 'STRING', 'NUMBER'):
                        key_str = k[1]
                        self.pos += 1
                        if self.match('PUNCT', ':'):
                            val = self.parse_expression(prec=1)
                            props.append((key_str, val))
                        elif self.curr()[0] == 'PUNCT' and self.curr()[1] == '(':
                            self.expect('PUNCT', '(')
                            m_params = []
                            if not (self.curr()[0] == 'PUNCT' and self.curr()[1] == ')'):
                                while True:
                                    m_params.append(self.expect('IDENT')[1])
                                    if not self.match('PUNCT', ','): break
                            self.expect('PUNCT', ')')
                            m_body = self.parse_block()
                            props.append((key_str, ASTNode('FunctionExpression', id=key_str, params=m_params, body=m_body)))
                        else:
                            props.append((key_str, ASTNode('Identifier', name=key_str)))
                    if not self.match('PUNCT', ','): break
            self.expect('PUNCT', '}')
            return ASTNode('ObjectExpression', properties=props, line=t[2], col=t[3])

        raise SyntaxError(f"Unexpected token '{t[1]}' at line {t[2]}, column {t[3]}")

# --- Evaluator ---
def eval_node(node, env):
    if node is None:
        return JS_UNDEFINED

    ntype = node.type

    if ntype == 'Program':
        val = JS_UNDEFINED
        for stmt in node.body:
            val = eval_node(stmt, env)
        return val

    elif ntype == 'BlockStatement':
        block_env = Environment(env)
        val = JS_UNDEFINED
        for stmt in node.body:
            val = eval_node(stmt, block_env)
        return val

    elif ntype == 'EmptyStatement':
        return JS_UNDEFINED

    elif ntype == 'ExpressionStatement':
        return eval_node(node.expression, env)

    elif ntype == 'VariableDeclaration':
        for decl in node.declarations:
            val = eval_node(decl.init, env) if decl.init else JS_UNDEFINED
            env.declare(decl.id, val, node.kind)
        return JS_UNDEFINED

    elif ntype == 'FunctionDeclaration':
        fn = JSFunction(node.id, node.params, node.body, env)
        env.declare(node.id, fn, 'function')
        return JS_UNDEFINED

    elif ntype == 'IfStatement':
        test_val = eval_node(node.test, env)
        if js_truthy(test_val):
            return eval_node(node.consequent, env)
        elif node.alternate:
            return eval_node(node.alternate, env)
        return JS_UNDEFINED

    elif ntype == 'WhileStatement':
        val = JS_UNDEFINED
        while js_truthy(eval_node(node.test, env)):
            try:
                val = eval_node(node.body, env)
            except BreakException:
                break
            except ContinueException:
                continue
        return val

    elif ntype == 'DoWhileStatement':
        val = JS_UNDEFINED
        while True:
            try:
                val = eval_node(node.body, env)
            except BreakException:
                break
            except ContinueException:
                pass
            if not js_truthy(eval_node(node.test, env)):
                break
        return val

    elif ntype == 'ForStatement':
        for_env = Environment(env)
        if node.init:
            eval_node(node.init, for_env)
        val = JS_UNDEFINED
        while node.test is None or js_truthy(eval_node(node.test, for_env)):
            try:
                val = eval_node(node.body, for_env)
            except BreakException:
                break
            except ContinueException:
                pass
            if node.update:
                eval_node(node.update, for_env)
        return val

    elif ntype == 'ForInStatement':
        for_env = Environment(env)
        obj = eval_node(node.right, for_env)
        val = JS_UNDEFINED
        keys = obj.own_keys() if isinstance(obj, JSObject) else []
        var_name = node.left.declarations[0].id if node.left.type == 'VariableDeclaration' else node.left.name
        for k in keys:
            for_env.declare(var_name, k)
            try:
                val = eval_node(node.body, for_env)
            except BreakException:
                break
            except ContinueException:
                continue
        return val

    elif ntype == 'ForOfStatement':
        for_env = Environment(env)
        arr = eval_node(node.right, for_env)
        val = JS_UNDEFINED
        items = arr.items if isinstance(arr, JSArray) else []
        var_name = node.left.declarations[0].id if node.left.type == 'VariableDeclaration' else node.left.name
        for item in items:
            for_env.declare(var_name, item)
            try:
                val = eval_node(node.body, for_env)
            except BreakException:
                break
            except ContinueException:
                continue
        return val

    elif ntype == 'ReturnStatement':
        val = eval_node(node.argument, env) if node.argument else JS_UNDEFINED
        raise ReturnException(val)

    elif ntype == 'BreakStatement':
        raise BreakException()

    elif ntype == 'ContinueStatement':
        raise ContinueException()

    elif ntype == 'ThrowStatement':
        val = eval_node(node.argument, env)
        raise JSException(val)

    elif ntype == 'TryStatement':
        try:
            return eval_node(node.block, env)
        except JSException as ex:
            if node.handler:
                catch_env = Environment(env)
                if node.handler.param:
                    catch_env.declare(node.handler.param, ex.value)
                return eval_node(node.handler.body, catch_env)
        finally:
            if node.finalizer:
                eval_node(node.finalizer, env)
        return JS_UNDEFINED

    elif ntype == 'SwitchStatement':
        disc = eval_node(node.discriminant, env)
        matched = False
        val = JS_UNDEFINED
        for case in node.cases:
            if not matched:
                if case.test is None:
                    matched = True
                else:
                    c_val = eval_node(case.test, env)
                    if c_val == disc:
                        matched = True
            if matched:
                try:
                    for stmt in case.consequent:
                        val = eval_node(stmt, env)
                except BreakException:
                    break
        return val

    elif ntype == 'Literal':
        return node.value

    elif ntype == 'Identifier':
        return env.get(node.name)

    elif ntype == 'ArrayExpression':
        items = [eval_node(el, env) for el in node.elements]
        return JSArray(items)

    elif ntype == 'ObjectExpression':
        obj = JSObject(OBJECT_PROTOTYPE)
        for key, val_node in node.properties:
            obj.set(key, eval_node(val_node, env))
        return obj

    elif ntype == 'FunctionExpression' or ntype == 'ArrowFunctionExpression':
        return JSFunction(getattr(node, 'id', None), node.params, node.body, env)

    elif ntype == 'MemberExpression':
        obj = eval_node(node.object, env)
        if obj is JS_UNDEFINED or obj is JS_NULL:
            raise JSException(create_error("TypeError", f"cannot read property of {obj}"))
        prop = eval_node(node.property, env) if node.computed else node.property
        if isinstance(obj, JSObject):
            return obj.get(prop)
        elif isinstance(obj, str):
            if prop == 'length': return len(obj)
            if str(prop).isdigit(): return obj[int(prop)]
            return STRING_PROTOTYPE.get(prop)
        return JS_UNDEFINED

    elif ntype == 'CallExpression':
        if node.callee.type == 'MemberExpression':
            obj = eval_node(node.callee.object, env)
            prop = eval_node(node.callee.property, env) if node.callee.computed else node.callee.property
            fn = obj.get(prop) if isinstance(obj, JSObject) else (STRING_PROTOTYPE.get(prop) if isinstance(obj, str) else JS_UNDEFINED)
            this_val = obj
        else:
            fn = eval_node(node.callee, env)
            this_val = GLOBAL_OBJECT

        if not isinstance(fn, JSFunction):
            raise JSException(create_error("TypeError", "not a function"))

        args = [eval_node(arg, env) for arg in node.arguments]
        return fn.call(this_val, args)

    elif ntype == 'NewExpression':
        fn = eval_node(node.callee, env)
        if not isinstance(fn, JSFunction):
            raise JSException(create_error("TypeError", "not a constructor"))
        new_obj = JSObject(fn.get('prototype'))
        args = [eval_node(arg, env) for arg in node.arguments]
        res = fn.call(new_obj, args)
        return res if isinstance(res, JSObject) else new_obj

    elif ntype == 'UnaryExpression':
        op = node.operator
        arg = eval_node(node.argument, env)
        if op == '+': return float(arg) if '.' in str(arg) else int(arg)
        elif op == '-': return -arg
        elif op == '!': return not js_truthy(arg)
        elif op == '~': return ~int(arg)
        elif op == 'typeof':
            if arg is JS_UNDEFINED: return "undefined"
            if arg is JS_NULL: return "object"
            if isinstance(arg, bool): return "boolean"
            if isinstance(arg, (int, float)): return "number"
            if isinstance(arg, str): return "string"
            if isinstance(arg, JSFunction): return "function"
            if isinstance(arg, JSObject): return "object"
            return "undefined"
        elif op == 'delete':
            if node.argument.type == 'MemberExpression':
                obj = eval_node(node.argument.object, env)
                prop = eval_node(node.argument.property, env) if node.argument.computed else node.argument.property
                if isinstance(obj, JSObject): return obj.delete(prop)
            return True
        elif op == 'void': return JS_UNDEFINED

    elif ntype == 'UpdateExpression':
        op = node.operator
        prefix = node.prefix
        if node.argument.type == 'Identifier':
            old_val = env.get(node.argument.name)
            new_val = old_val + 1 if op == '++' else old_val - 1
            env.set(node.argument.name, new_val)
            return new_val if prefix else old_val
        elif node.argument.type == 'MemberExpression':
            obj = eval_node(node.argument.object, env)
            prop = eval_node(node.argument.property, env) if node.argument.computed else node.argument.property
            old_val = obj.get(prop)
            new_val = old_val + 1 if op == '++' else old_val - 1
            obj.set(prop, new_val)
            return new_val if prefix else old_val

    elif ntype == 'BinaryExpression':
        left = eval_node(node.left, env)
        right = eval_node(node.right, env)
        op = node.operator
        if op == '+':
            if isinstance(left, str) or isinstance(right, str):
                return js_to_string(left) + js_to_string(right)
            return left + right
        elif op == '-': return left - right
        elif op == '*': return left * right
        elif op == '/': return left / right if right != 0 else float('inf')
        elif op == '%': return left % right
        elif op == '**': return left ** right
        elif op == '==': return left == right
        elif op == '!=': return left != right
        elif op == '===': return type(left) == type(right) and left == right
        elif op == '!==': return type(left) != type(right) or left != right
        elif op == '<': return left < right
        elif op == '<=': return left <= right
        elif op == '>': return left > right
        elif op == '>=': return left >= right
        elif op == 'in':
            return right.has(left) if isinstance(right, JSObject) else False

    elif ntype == 'LogicalExpression':
        op = node.operator
        left = eval_node(node.left, env)
        if op == '&&':
            return eval_node(node.right, env) if js_truthy(left) else left
        elif op == '||':
            return left if js_truthy(left) else eval_node(node.right, env)
        elif op == '??':
            return left if (left is not JS_UNDEFINED and left is not JS_NULL) else eval_node(node.right, env)

    elif ntype == 'ConditionalExpression':
        test = eval_node(node.test, env)
        return eval_node(node.consequent, env) if js_truthy(test) else eval_node(node.alternate, env)

    elif ntype == 'AssignmentExpression':
        op = node.operator
        right = eval_node(node.right, env)
        if node.left.type == 'Identifier':
            if op == '=': val = right
            else:
                old = env.get(node.left.name)
                val = (old + right) if op == '+=' else ((old - right) if op == '-=' else (old * right))
            env.set(node.left.name, val)
            return val
        elif node.left.type == 'MemberExpression':
            obj = eval_node(node.left.object, env)
            prop = eval_node(node.left.property, env) if node.left.computed else node.left.property
            if op == '=': val = right
            else:
                old = obj.get(prop)
                val = (old + right) if op == '+=' else ((old - right) if op == '-=' else (old * right))
            obj.set(prop, val)
            return val

    elif ntype == 'ImportDeclaration':
        source = node.source
        if source == 'std':
            mod = STD_MODULE
        elif source == 'os':
            mod = OS_MODULE
        else:
            mod = JSObject(OBJECT_PROTOTYPE)
        for spec in node.specifiers:
            if spec[0] == 'namespace':
                env.declare(spec[1], mod)
            elif spec[0] == 'named':
                env.declare(spec[2], mod.get(spec[1]))
        return JS_UNDEFINED

    return JS_UNDEFINED

# --- Main CLI ---
HELP_TEXT = """QuickJS version 2025-09-13
usage: qjs [options] [file [args]]
-h  --help         list options
-e  --eval EXPR    evaluate EXPR
-i  --interactive  go to interactive mode
-m  --module       load as ES6 module (default=autodetect)
    --script       load as ES6 script (default=autodetect)
    --strict       force strict mode
-I  --include file include an additional file
    --std          make 'std' and 'os' available to the loaded script
-T  --trace        trace memory allocation
-d  --dump         dump the memory usage stats
    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)
    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)
    --no-unhandled-rejection  ignore unhandled promise rejections
-s                    strip all the debug info
    --strip-source    strip the source code
-q  --quit         just instantiate the interpreter and quit"""

def main():
    args = sys.argv[1:]
    eval_expr = None
    interactive = False
    use_std = False
    include_files = []
    quit_early = False
    dump_mem = False

    i = 0
    script_file = None
    script_args = []

    while i < len(args):
        arg = args[i]
        if arg in ('-h', '--help'):
            print(HELP_TEXT)
            sys.exit(1)
        elif arg in ('-e', '--eval'):
            i += 1
            if i < len(args):
                eval_expr = args[i]
        elif arg in ('-i', '--interactive'):
            interactive = True
        elif arg == '--std':
            use_std = True
        elif arg in ('-I', '--include'):
            i += 1
            if i < len(args):
                include_files.append(args[i])
        elif arg in ('-q', '--quit'):
            quit_early = True
        elif arg in ('-d', '--dump'):
            dump_mem = True
        elif arg in ('-T', '--trace', '-s', '--strip-source', '--strict', '-m', '--module', '--script', '--no-unhandled-rejection'):
            pass
        elif arg in ('--memory-limit', '--stack-size'):
            i += 1
        elif arg.startswith('-'):
            sys.stderr.write(f"qjs: unknown option '{arg}'\n")
            print(HELP_TEXT)
            sys.exit(1)
        else:
            if eval_expr is not None:
                script_args = args[i:]
            else:
                script_file = arg
                script_args = args[i:]
            break
        i += 1

    global STD_MODULE, OS_MODULE
    STD_MODULE, OS_MODULE = setup_builtins()

    if use_std:
        GLOBAL_OBJECT.set('std', STD_MODULE)
        GLOBAL_ENV.declare('std', STD_MODULE)
        GLOBAL_OBJECT.set('os', OS_MODULE)
        GLOBAL_ENV.declare('os', OS_MODULE)

    GLOBAL_OBJECT.set('globalThis', GLOBAL_OBJECT)
    GLOBAL_ENV.declare('globalThis', GLOBAL_OBJECT)

    script_args_obj = JSArray([script_file] + script_args if script_file else script_args)
    GLOBAL_OBJECT.set('scriptArgs', script_args_obj)
    GLOBAL_ENV.declare('scriptArgs', script_args_obj)

    if quit_early:
        sys.exit(0)

    # Evaluate included files
    for inc in include_files:
        try:
            with open(inc, 'r', encoding='utf-8') as f:
                code = f.read()
            tokens = tokenize(code)
            parser = Parser(tokens)
            ast = parser.parse_program()
            eval_node(ast, GLOBAL_ENV)
        except Exception as e:
            sys.stderr.write(f"Error loading {inc}: {e}\n")
            sys.exit(1)

    # Evaluate -e or script file
    if eval_expr is not None:
        try:
            tokens = tokenize(eval_expr)
            parser = Parser(tokens)
            ast = parser.parse_program()
            eval_node(ast, GLOBAL_ENV)
        except JSException as jse:
            err = jse.value
            msg = err.get('message') if isinstance(err, JSObject) else str(err)
            name = err.get('name') if isinstance(err, JSObject) else "Error"
            sys.stderr.write(f"{name}: {msg}\n    at <eval> (<cmdline>:1:1)\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)
    elif script_file is not None:
        try:
            with open(script_file, 'r', encoding='utf-8') as f:
                code = f.read()
            tokens = tokenize(code)
            parser = Parser(tokens)
            ast = parser.parse_program()
            eval_node(ast, GLOBAL_ENV)
        except JSException as jse:
            err = jse.value
            msg = err.get('message') if isinstance(err, JSObject) else str(err)
            name = err.get('name') if isinstance(err, JSObject) else "Error"
            sys.stderr.write(f"{name}: {msg}\n    at <eval> ({script_file}:1:1)\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)
    else:
        # REPL mode
        print('QuickJS - Type "\\h" for help')
        while True:
            try:
                line = input('qjs > ')
                if line.strip() == '\\q':
                    break
                elif line.strip() == '\\h':
                    print('\\h          this help')
                    print('\\x          hexadecimal number display')
                    print('\\d         *decimal number display')
                    print('\\t          toggle timing display')
                    print('\\clear      clear the terminal')
                    print('\\q          exit')
                    continue
                elif line.strip() == '\\clear':
                    os.system('clear')
                    continue
                elif line.startswith('\\'):
                    continue

                if not line.strip(): continue

                tokens = tokenize(line)
                parser = Parser(tokens)
                ast = parser.parse_program()
                res = eval_node(ast, GLOBAL_ENV)
                if res is not JS_UNDEFINED:
                    print(js_format_val(res))
            except (EOFError, KeyboardInterrupt):
                break
            except JSException as jse:
                err = jse.value
                msg = err.get('message') if isinstance(err, JSObject) else str(err)
                name = err.get('name') if isinstance(err, JSObject) else "Error"
                print(f"{name}: {msg}")
            except Exception as e:
                print(f"SyntaxError: {e}")

if __name__ == '__main__':
    main()
